// Acceptance B, printed rail: a pinion rolls as a follower along a curved
// guide, and the rail it needs is generated by rolling the pinion outline.
import assert from 'node:assert/strict';
import {involuteOutline} from '../../src/mechanics/kinematics/generate/involute.ts';
import {railProfile,railMesh,crossings,pinionAt} from '../../src/mechanics/kinematics/generate/rail.ts';
import {stl,watertight,volume} from '../../src/mechanics/kinematics/generate/mesh.ts';
import {curve} from '../../src/mechanics/kinematics/curves.ts';
import {closestArc} from '../../src/mechanics/kinematics/contacts.ts';
import {solve} from '../../src/mechanics/kinematics/solver.ts';
import {spurSurface} from '../../src/mechanics/kinematics/surfaces.ts';
import {identity,dot,add,scale} from '../../src/mechanics/kinematics/math.ts';

const close=(a,b,tol,what)=>assert.ok(Math.abs(a-b)<=tol,`${what}: ${a} vs ${b}`);
const m=2,z=20,ra=m*z/2,backlash=.15,alpha=20*Math.PI/180;

// Involute outline: z teeth, star shaped, tooth thickness at the pitch circle.
{const o=involuteOutline({module:m,teeth:z,backlash});let prev=-Infinity,turns=0;
 for(const [x,y] of o){const a=Math.atan2(y,x);if(a<prev-Math.PI)turns++;prev=a;}assert.equal(turns,1,'outline winds once');
 const radii=o.map(([x,y])=>Math.hypot(x,y));close(Math.max(...radii),ra+m,1e-9,'tip radius');close(Math.min(...radii),ra-1.25*m,1e-9,'root radius');}

// Straight rack: pitch πm, flank angle 20°, tooth thickness πm/2 + backlash/2 at the pitch line.
{const p=railProfile({path:{kind:'line',length:200},module:m,pinionTeeth:z,backlash,from:20,to:140,width:10});
 const pitch=crossings(p,0),rising=pitch.filter(c=>c.rising).map(c=>c.s);
 for(let i=1;i<rising.length;i++)close(rising[i]-rising[i-1],Math.PI*m,.03,'rack pitch');
 const thick=level=>{const c=crossings(p,level),out=[];for(let i=0;i<c.length-1;i++)if(c[i].rising&&!c[i+1].rising)out.push(c[i+1].s-c[i].s);return out.reduce((a,b)=>a+b,0)/out.length;};
 close(thick(0),Math.PI*m/2+backlash/2,.04,'tooth thickness at pitch line');
 close(thick(-.5*m)-thick(.5*m),2*m*Math.tan(alpha),.05,'flank angle');
 const mesh=railMesh(p);assert.ok(watertight(mesh),'straight rail mesh is closed');assert.ok(volume(mesh)>0,'outward oriented');
 assert.ok(stl(mesh,'rack').startsWith('solid rack'));}

// Curved guide like a garage door track, scaled: straight – arc R 120 – straight.
const guide={kind:'path',points:[[0,0,0],[0,200,0],[200,200,0]],closed:false,cornerRadius:120,axis:[0,0,1]};
const fn=curve(guide),arcFrom=200-120,arcTo=arcFrom+Math.PI*120/2;
for(const side of [1,-1]){
 const p=railProfile({path:guide,module:m,pinionTeeth:z,backlash,side,from:arcFrom-30,to:arcTo+30,width:12});
 const teeth=crossings(p,0).filter(c=>c.rising).length,expected=(p.s.at(-1)-p.s[0])/(Math.PI*m);
 assert.ok(Math.abs(teeth-expected)<=1.5,`side ${side}: ${teeth} teeth over ${expected.toFixed(1)} pitches`);
 // Independent check: the pinion between the sampled poses never cuts into the rail beyond 0.03 mm.
 let worst=0;
 for(let c=arcFrom-20;c<=arcTo+20;c+=.037){for(const q of pinionAt(p,c)){const sa=closestArc(fn,q,c);if(sa<p.s[0]||sa>p.s.at(-1))continue;const h=side*dot(add(q,scale(fn.point(sa),-1)),fn.normal(sa));if(h>p.addendum)continue;
  const f=(sa-p.s[0])/(p.s[1]-p.s[0]),i=Math.max(0,Math.min(p.s.length-2,Math.floor(f))),w=f-i,top=p.top[i]*(1-w)+p.top[i+1]*w;worst=Math.max(worst,top-h);}}
 assert.ok(worst<.03,`side ${side}: pinion penetrates the generated rail by ${worst.toFixed(4)} mm`);
 const mesh=railMesh(p);assert.ok(watertight(mesh),`side ${side}: curved rail mesh is closed`);assert.ok(volume(mesh)>0,`side ${side}: outward oriented`);
}
assert.throws(()=>railProfile({path:{kind:'path',points:[[0,0,0],[0,100,0],[100,100,0]],closed:false,cornerRadius:15,axis:[0,0,1]},module:m,pinionTeeth:z,side:-1,from:60,to:120,width:10}),/Krümmungsradius/,'pinion inside a tight bend is rejected');

// Follower: a carriage on the guide carries the pinion; rolling ties pinion angle to travel, also through the arc.
for(const side of [1,-1]){
 const pinion={id:'pinion',source:{kind:'printed'},surfaces:[spurSurface('teeth',m,z,10)],interfaces:[{id:'bore',kind:'bore',diameter:5,z:[-5,5]}],envelope:{radius:ra+m,min:-5,max:5},mounts:[{interface:'bore',body:'pinion',pose:identity()}],phase:0};
 const rail={id:'rail',source:{kind:'printed'},surfaces:[{id:'teeth',pitch:guide,profile:{kind:'involute',module:m,pressureAngle:20,backlash},z:[-6,6],side:'external'}],interfaces:[{id:'flange',kind:'flange',frame:identity()}],envelope:{radius:0,min:-6,max:6},mounts:[{interface:'flange',body:'ground',pose:identity()}],phase:0};
 const s0=50,start=fn.frame(s0),centre=add(start.position,scale(fn.normal(s0),side*ra));
 const doc={format:'kinematics-1',parameters:[],patterns:[],bodies:[{id:'ground',frame:identity(),ground:true},{id:'carriage',frame:start},{id:'pinion',frame:{position:centre,rotation:start.rotation}}],
  joints:[{id:'track',joint:{kind:'path',curve:guide,roll:'locked'},a:{body:'ground',local:identity()},b:{body:'carriage',local:identity()}},
   {id:'axle',joint:{kind:'revolute'},a:{body:'carriage',local:{position:[0,side*ra,0],rotation:[0,0,0,1]}},b:{body:'pinion',local:identity()}}],
  elements:[pinion,rail],contacts:[{id:'mesh',kind:'roll',mode:'follower',a:{element:'pinion',surface:'teeth'},b:{element:'rail',surface:'teeth'},params:{offsetA:0,offsetB:0,side}}],
  input:{kind:'coordinate',joint:'axle',coordinate:0},output:{kind:'coordinate',joint:'track',coordinate:0},range:{from:0,to:-side*720,samples:25}};
 const r=await solve(doc,{yield:false});
 assert.equal(r.checks.find(c=>c.id==='closure').state,'pass',r.checks.find(c=>c.id==='closure').message);
 assert.equal(r.checks.find(c=>c.id==='mobility').state,'pass',r.mobility.message);
 for(const {input,output} of r.transfer.samples)close(output-s0,-side*ra*input*Math.PI/180,1e-4,`side ${side} travel at ${input}°`);
 assert.ok(r.transfer.samples.at(-1).output>arcTo,'carriage passes the whole arc');
}
console.log('Kinematics rail: involute outline, straight rack geometry, curved rails on both sides without interference, closed meshes and pinion follower through the arc passed.');
